replace:
const basename = path.basename(dep);
const fullPath = path.join(cwd, dep);
const file = await fs.promises.open(fullPath, 'r');
const signature = Buffer.alloc(2);
try {
	await file.read(signature, 0, signature.length, 0);
} finally {
	await file.close();
}
if (signature[0] !== 0x4d || signature[1] !== 0x5a) {
	return;
}

await stripAuthenticodeSignature(fullPath);
